import type { NextginExport } from './export.js'
import { goPrefixes } from './prefixes.js'

export type WebTarget = 'vercel'
export type BackendTarget = 'container'
export type ApiMode = 'rewrite' | 'direct'

export interface SplitOptions {
  webTarget: WebTarget
  backendTarget: BackendTarget
  backendUrl: string
  backendHostname: string
  apiMode: ApiMode
}

export interface VercelSplitConfig {
  rewrites?: Array<{
    source: string
    destination: string
  }>
}

export const DOCKER_GENERATED_MARKER =
  '# generated by nextgin — edits are overwritten; remove this line to take ownership'

/**
 * Validates and normalizes `--backend-url` to its origin without a trailing slash.
 */
export function validateBackendUrl(rawUrl: unknown, backendTarget: BackendTarget): string {
  if (typeof rawUrl !== 'string' || rawUrl.trim() === '') {
    throw new Error('--backend-url is required')
  }

  let url: URL
  try {
    url = new URL(rawUrl)
  } catch {
    throw new Error(`invalid --backend-url "${rawUrl}"`)
  }

  const isLocalHttp =
    url.protocol === 'http:' && (url.hostname === 'localhost' || url.hostname === '127.0.0.1')
  if (url.protocol !== 'https:' && !isLocalHttp) {
    throw new Error('--backend-url must use https (http is only allowed for localhost or 127.0.0.1)')
  }

  if (url.username !== '' || url.password !== '') {
    throw new Error('--backend-url must not include credentials')
  }

  if (url.search !== '' || rawUrl.includes('?')) {
    throw new Error('--backend-url must not include a query string')
  }

  if (url.hash !== '' || rawUrl.includes('#')) {
    throw new Error('--backend-url must not include a hash')
  }

  if (url.pathname !== '' && url.pathname !== '/') {
    throw new Error('--backend-url must not include a path')
  }

  return url.origin
}

/**
 * Validates split-topology CLI flags and returns normalized options.
 */
export function validateSplitFlags(flags: Record<string, string | boolean>): SplitOptions {
  if (flags.target !== undefined) {
    throw new Error('--target cannot be combined with --web-target/--backend-target')
  }

  if (flags['web-target'] === undefined) {
    throw new Error('--web-target is required when --backend-target is set')
  }

  if (flags['backend-target'] === undefined) {
    throw new Error('--backend-target is required when --web-target is set')
  }

  if (flags['web-target'] !== 'vercel') {
    throw new Error('only vercel is supported as --web-target for now')
  }

  const backendTarget = flags['backend-target']
  if (backendTarget !== 'container') {
    throw new Error('--backend-target must be "container"')
  }

  const backendUrl = validateBackendUrl(flags['backend-url'], backendTarget)
  const backendHostname = new URL(backendUrl).hostname

  const rawApiMode = flags['api-mode']
  let apiMode: ApiMode = 'direct'
  if (rawApiMode !== undefined) {
    if (rawApiMode !== 'rewrite' && rawApiMode !== 'direct') {
      throw new Error('--api-mode must be "direct" or "rewrite"')
    }
    apiMode = rawApiMode
  }

  return {
    webTarget: 'vercel',
    backendTarget,
    backendUrl,
    backendHostname,
    apiMode,
  }
}

/**
 * Builds `<webDir>/vercel.json` for a split-topology deployment.
 */
export function generateVercelSplitConfig(
  exp: NextginExport,
  opts: { backendUrl: string; apiMode: ApiMode },
): VercelSplitConfig {
  if (opts.apiMode === 'direct') {
    return {}
  }

  const prefixes = goPrefixes(exp)
  return {
    rewrites: prefixes.map((prefix) => ({
      source: `/${prefix}/:path*`,
      destination: `${opts.backendUrl}/${prefix}/:path*`,
    })),
  }
}

/**
 * Extracts `<major>.<minor>` from the first `go <major>.<minor>` directive in `go.mod`.
 */
export function parseGoVersion(goMod: string): string {
  for (const line of goMod.split(/\r?\n/)) {
    const match = /^go\s+(\d+)\.(\d+)/.exec(line.trim())
    if (match) {
      return `${match[1]}.${match[2]}`
    }
  }
  throw new Error('go.mod has no `go <major>.<minor>` directive')
}

/**
 * Returns true if a Dockerfile does not exist or still starts with the generated-file marker.
 */
export function canOverwriteDockerfile(existing: string | undefined): boolean {
  if (existing === undefined) return true
  const firstLine = existing.split(/\r?\n/, 1)[0]
  return firstLine === DOCKER_GENERATED_MARKER
}

/**
 * Generates the multi-stage Dockerfile for `--backend-target container`.
 */
export function generateDockerfile(opts: { goVersion: string }): string {
  return `${DOCKER_GENERATED_MARKER}
FROM golang:${opts.goVersion} AS build
WORKDIR /src
COPY go.mod go.sum* ./
RUN go mod download
COPY . .
RUN CGO_ENABLED=0 go build -trimpath -ldflags="-s -w" -o /out/server .

FROM gcr.io/distroless/static-debian12:nonroot
COPY --from=build /out/server /server
ENV NEXTGIN_TARGET=backend
ENV PORT=8080
EXPOSE 8080
ENTRYPOINT ["/server"]
`
}
